values.value:
{
 "type": "object",
 "properties": {
  "items": {
   "type": "array",
   "maxItems": 25,
   "items": {
    "type": "object",
    "properties": {
     "kind": {
      "type": "string",
      "enum": [
       "title",
       "skill",
       "certification",
       "location",
       "keyword",
       "language",
       "shift",
       "availability"
      ]
     },
     "label": {
      "type": "string",
      "description": "Chip text shown to the user, max 120 characters. For a location: 'Town + N mi'."
     },
     "value": {
      "type": "string",
      "description": "Term sent to the search. Town or postcode for a location."
     },
     "weight": {
      "type": "string",
      "enum": [
       "required",
       "strongly_preferred",
       "preferred",
       "excluded"
      ]
     },
     "radius": {
      "type": "number",
      "description": "Location only."
     },
     "unit": {
      "type": "string",
      "enum": [
       "mi",
       "km"
      ],
      "description": "Location only."
     },
     "withinDays": {
      "type": "integer",
      "description": "Availability only: available within this many days of Today."
     }
    },
    "required": [
     "kind",
     "label",
     "value",
     "weight"
    ]
   }
  },
  "filters": {
   "type": "object",
   "description": "Facet field to selected values. Only candidate_status is supported by the parser.",
   "properties": {
    "candidate_status": {
     "type": "array",
     "items": {
      "type": "string"
     }
    }
   }
  },
  "exclusions": {
   "type": "object",
   "properties": {
    "placedWithinDays": {
     "type": "integer",
     "description": "Exclude anyone placed within this many days."
    },
    "pipelineForJob": {
     "type": "boolean",
     "description": "Hide candidates already applied, shortlisted or placed on the job."
    }
   }
  }
 },
 "required": [
  "items"
 ]
}
